import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        HashMap<Long, Integer> seen = new HashMap<>(4 * n);
        long answer = 0;
        for (int t = 0; t < n; t++) {
            long value = nextLong();
            char[] digits = Long.toString(value).toCharArray();
            // Values reachable with zero or one swap of two digit positions, deduplicated.
            TreeSet<Long> reachable = new TreeSet<>();
            reachable.add(value);
            for (int i = 0; i < digits.length; i++)
                for (int j = i + 1; j < digits.length; j++) {
                    char tmp = digits[i];
                    digits[i] = digits[j];
                    digits[j] = tmp;
                    reachable.add(Long.parseLong(new String(digits)));  // leading zeros are dropped
                    digits[j] = digits[i];
                    digits[i] = tmp;
                }
            for (long candidate : reachable) answer += seen.getOrDefault(candidate, 0);
            seen.merge(value, 1, Integer::sum);
        }
        System.out.println(answer);
    }
}

