import (
	"fmt"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	seen := make(map[int]int, 2*n)
	answer := 0
	for t := 0; t < n; t++ {
		value := nextInt()
		digits := []byte(strconv.Itoa(value))
		// Values reachable with zero or one swap of two digit positions, deduplicated.
		reachable := map[int]struct{}{value: {}}
		for i := 0; i < len(digits); i++ {
			for j := i + 1; j < len(digits); j++ {
				digits[i], digits[j] = digits[j], digits[i]
				v, _ := strconv.Atoi(string(digits)) // leading zeros are dropped
				reachable[v] = struct{}{}
				digits[i], digits[j] = digits[j], digits[i]
			}
		}
		for candidate := range reachable {
			answer += seen[candidate]
		}
		seen[value]++
	}
	fmt.Println(answer)
}
